/**
 * GWP V1 wire schema mirrors (architecture §7) — the variant tables are
 * generated from the published `gwp-schema.json` (regenerated by
 * `guiwright-proto::schemadoc`, golden-pinned in Rust AND re-pinned by
 * `test/schema.test.ts` against the copy vendored here).
 *
 * Wire discipline: variants are append-only within the `V1` envelope —
 * `Video` follows `Bye` (M3), the `Window` domain follows `Video`
 * (M6, §16 v0.4 multi-window); a mid-enum reorder fails the Rust
 * discriminant pinning test and the schema golden at the same time.
 */

// --- Envelopes ---------------------------------------------------------------

/** Current protocol version (Rust `PROTO_VERSION`, §7). */
export const PROTO_VERSION = 1;

export const GwpRequest = { V1: 0 } as const;
export const GwpResponse = { V1: 0 } as const;
export const GwpEvent = { V1: 0 } as const;

// --- Request variants (index = postcard discriminant) ------------------------

export const RequestV1 = {
  Hello: 0,
  Ping: 1,
  TreeSnapshot: 2,
  Resolve: 3,
  Action: 4,
  Input: 5,
  Clock: 6,
  Mock: 7,
  Inspect: 8,
  Bye: 9,
  Video: 10,
  Window: 11,
} as const;

export const ClockV1 = {
  InstallVirtual: 0,
  FastForward: 1,
  RunFor: 2,
  Pause: 3,
  Resume: 4,
  SetTime: 5,
  State: 6,
} as const;

export const MockV1 = {
  InstallSeam: 0,
  Clear: 1,
  ResetState: 2,
  Call: 3,
} as const;

export const InspectV1 = {
  StartRecording: 0,
  StopRecording: 1,
} as const;

export const VideoV1 = {
  Start: 0,
  Stop: 1,
} as const;

export const WindowV1 = {
  List: 0,
  Use: 1,
} as const;

// --- Response variants -------------------------------------------------------

export const ResponseV1 = {
  Welcome: 0,
  Pong: 1,
  TreeSnapshot: 2,
  Resolved: 3,
  ActionDone: 4,
  InputQueued: 5,
  ClockState: 6,
  MockDone: 7,
  Codegen: 8,
  Error: 9,
  Bye: 10,
  VideoFile: 11,
  Windows: 12,
  WindowUsed: 13,
} as const;

export const ErrorCode = {
  UnsupportedVersion: 0,
  NotHandshaked: 1,
  UnknownNode: 2,
  StaleGeneration: 3,
  StrictModeViolation: 4,
  Timeout: 5,
  Unsupported: 6,
  Internal: 7,
  UnknownWindow: 8,
} as const;

// --- Nested payload enums ----------------------------------------------------

export const NodeKeyV1 = {
  AccessKit: 0,
  Logical: 1,
} as const;

export const SelectorV1 = {
  Role: 0,
  Label: 1,
  Text: 2,
  TestId: 3,
  Value: 4,
  All: 5,
  Filter: 6,
} as const;

export const NthV1 = { First: 0, Last: 1, Index: 2 } as const;

export const SemActionV1 = {
  Click: 0,
  DoubleClick: 1,
  SetValue: 2,
  Focus: 3,
  Blur: 4,
  Hover: 5,
  Press: 6,
  Scroll: 7,
  Check: 8,
  Uncheck: 9,
} as const;

export const InputEventV1 = {
  PointerDown: 0,
  PointerUp: 1,
  PointerMove: 2,
  Wheel: 3,
  KeyDown: 4,
  KeyUp: 5,
  TextInput: 6,
} as const;

export const PointerButtonV1 = {
  Primary: 0,
  Secondary: 1,
  Middle: 2,
} as const;

// --- Payload types (structs encode fields in declaration order) --------------

export interface TextMatchV1 {
  text: string;
  exact: boolean;
  ignore_case: boolean;
}

export interface VideoOptsV1 {
  /** 0 = the driver default (25 fps). */
  fps: number;
  /** Client-owned artifact dir (Playwright parity); null = driver default. */
  dir: string | null;
}

export interface AdapterInfoV1 {
  name: string;
  framework: string;
  framework_version: string;
  caps: CapsV1;
}

export interface CapsV1 {
  tree_update: boolean;
  logical_snapshot: boolean;
  input: boolean;
  last_frame: boolean;
  render_frame: boolean;
  clock: boolean;
}

export interface Welcome {
  proto_version: number;
  session_id: string;
  tree_seq: number;
  frame_seq: number;
  adapter: AdapterInfoV1;
}

export interface Resolved {
  node: NodeKey;
  generation: number;
  rect: [number, number, number, number] | null;
}

export type NodeKey =
  | { kind: "accesskit"; tree: string; node: number }  // tree = 32 hex chars (16 bytes)
  | { kind: "logical"; adapter: string; id: number };

export interface VideoFile {
  path: string;
  frames: number;
  dropped: number;
  duration_ms: number;
}

export interface ClockState {
  virtual_time_ms: number | null;
  paused: boolean;
  steps: number;
}

export interface MockDone {
  id: string;
  detail: string;
}

/** One window target (§16 v0.4): handle = subtree TreeId, or "main". */
export interface WindowInfoV1 {
  handle: string;
  title: string;
  focused: boolean;
}

// --- Request/response union types --------------------------------------------

export type GwpRequest =
  | { kind: "hello"; proto_version: number; agent: string }
  | { kind: "ping" }
  | { kind: "tree_snapshot" }
  | { kind: "resolve"; selector: Selector; timeout_ms: number }
  | {
      kind: "action";
      node: NodeKey;
      generation: number;
      action: SemAction;
      force: boolean;
      timeout_ms: number;
    }
  | { kind: "input"; events: InputEvent[] }
  | { kind: "clock"; cmd: ClockCmd }
  | { kind: "mock"; cmd: MockCmd }
  | { kind: "inspect"; cmd: InspectCmd }
  | { kind: "bye" }
  | { kind: "video"; cmd: VideoCmd }
  | { kind: "window"; cmd: WindowCmd };

export type Selector =
  | { kind: "role"; role: string; name: TextMatchV1 | null }
  | { kind: "label"; match: TextMatchV1 }
  | { kind: "text"; match: TextMatchV1 }
  | { kind: "test_id"; id: string }
  | { kind: "value"; match: TextMatchV1 }
  | { kind: "all"; selectors: Selector[] };

export type SemAction =
  | { kind: "click" }
  | { kind: "double_click" }
  | { kind: "set_value"; text: string }
  | { kind: "focus" }
  | { kind: "blur" }
  | { kind: "hover" }
  | { kind: "press"; key: string; modifiers: string[] }
  | { kind: "scroll"; dx: number; dy: number }
  | { kind: "check" }
  | { kind: "uncheck" };

export type InputEvent =
  | { kind: "pointer_down"; x: number; y: number; button: number }
  | { kind: "pointer_up"; x: number; y: number; button: number }
  | { kind: "pointer_move"; x: number; y: number }
  | { kind: "wheel"; dx: number; dy: number }
  | { kind: "key_down"; key: string; modifiers: string[] }
  | { kind: "key_up"; key: string; modifiers: string[] }
  | { kind: "text_input"; text: string };

export type ClockCmd =
  | { kind: "install_virtual" }
  | { kind: "fast_forward"; ms: number }
  | { kind: "run_for"; ms: number }
  | { kind: "pause" }
  | { kind: "resume" }
  | { kind: "set_time"; ms: number }
  | { kind: "state" };

export type MockCmd =
  | { kind: "install_seam"; id: string; response: string | null }
  | { kind: "clear"; id: string }
  | { kind: "reset_state"; scope: string }
  | { kind: "call"; id: string; scope: string };

export type InspectCmd = { kind: "start_recording" } | { kind: "stop_recording" };

export type VideoCmd =
  | { kind: "start"; opts: VideoOptsV1 }
  | { kind: "stop" };

/** §16 v0.4 multi-window: `Use` aims THIS connection at a window target. */
export type WindowCmd = { kind: "list" } | { kind: "use"; handle: string };

export type GwpResponse =
  | ({ kind: "welcome" } & Welcome)
  | { kind: "pong" }
  | { kind: "tree_snapshot"; tree_seq: number; node_count: number }
  | ({ kind: "resolved" } & Resolved)
  | { kind: "action_done"; frame_seq: number; detail: string }
  | { kind: "input_queued"; frame_seq: number }
  | ({ kind: "clock_state" } & ClockState)
  | ({ kind: "mock_done" } & MockDone)
  | { kind: "codegen"; code: string; warnings: string[] }
  | { kind: "error"; code: number; message: string }
  | { kind: "bye" }
  | ({ kind: "video_file" } & VideoFile)
  | { kind: "windows"; windows: WindowInfoV1[] }
  | { kind: "window_used"; handle: string };
